public int findLargestSubstring(List<String> strings) {
    String largestSubstring = "";
    int largestSubstringLength = 0;
    for (int i = 0; i < strings.size(); i++) {
        for (int j = i + 1; j < strings.size(); j++) {
            String substring = longCommonSubstring(strings.get(i), strings.get(j));
            if (substring.length() > largestSubstringLength) {
                largestSubstring = substring;
                largestSubstringLength = substring.length();
            }
        }
    }
    return largestSubstringLength;
}

private String longCommonSubstring(String str1, String str2) {
    int[][] dp = new int[str1.length() + 1][str2.length() + 1];
    for (int i = 1; i <= str1.length(); i++) {
        for (int j = 1; j <= str2.length(); j++) {
            if (str1.charAt(i - 1) == str2.charAt(j - 1)) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    int maxLength = 0;
    int startIndex = 0;
    for (int i = 0; i < str1.length(); i++) {
        for (int j = 0; j < str2.length(); j++) {
            if (dp[i][j] > maxLength) {
                maxLength = dp[i][j];
                startIndex = i - maxLength + 1;
            }
        }
    }
    return str1.substring(startIndex, startIndex + maxLength);
}
