    queue.offer(start);
    Set<int[]> visited = new HashSet<>();
    while (!queue.isEmpty()) {
        int[] currentPosition = queue.poll();
        if (Arrays.equals(currentPosition, end)) {
            return "can be travelled";
        }
        visited.add(currentPosition);
        for (int[] path : paths) {
            if (Arrays.equals(path, currentPosition)) {
                queue.offer(path);
            }
        }
