public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]] = true;
    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        for (int[] path : paths) {
            int nextX = current[0] + path[0];
            int nextY = current[1] + path[1];
            if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n && !visited[nextX][nextY]) {
                queue.offer(new int[] {nextX, nextY});
                visited[nextX][nextY] = true;
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
boolean visited[][] = new boolean[n][n];
traverse(start[0], start[1], visited);
return (visited[end[0]][end[1]]) ? "can be travelled" : "cannot be travelled";
}

public static void traverse(int row, int col, boolean[][] visited) {
if (!(row >= 0 && row < n && col >= 0 && col < n)) return;
if (visited[row][col]) return;
visited[row][col] = true;

for (int[] path : paths) {
if (path[0] == row && path[1] == col) {
int newRow = path[2] == -1 ? row : path[2];
int newCol = path[3] == -1 ? col : path[3];
traverse(newRow, newCol, visited);
}
}
}
