public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a set to store all visited n-tersections
    Set<int> visited = new HashSet<>();

    // Mark the starting n-tersection as visited
    visited.add(start[0]);

    // Initialize a queue to store the paths to be explored
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (current[0] == end[0]) {
            return "can be travelled";
        }

        // Loop through all the adjacent n-tersections
        for (int[] adjacent : paths) {
            // If the adjacent n-tersection has not been visited, mark it as visited and add it to the queue
            if (!visited.contains(adjacent[0])) {
                visited.add(adjacent[0]);
                queue.add(adjacent);
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    if (!visited.contains(end)) {
        return "cannot be travelled";
    }

    // If the ending n-tersection has been visited, return "can be travelled"
    return "can be travelled";
}
