public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int[] counts = new int[k];
    for (int i = 0; i < n; i++) {
        int num = arr[i];
        int j = num % k;
        if (j == 0) j = k;
        counts[j-1]++;
    }
    for (int i = 0; i < k; i++) {
        if (counts[i]*2 != n) return false;
    }
    return true;
}
