public boolean canArrange(int[] arr, int k) {
    int n = arr.length / 2;
    int[] counts = new int[k];
    for (int i = 0; i < n; i++) {
        int a = arr[i];
        int b = arr[i + n];
        int sum = a + b;
        counts[sum % k]++;
    }
    for (int i = 1; i < k; i++) {
        if (counts[i] != counts[k - i]) {
            return false;
        }
    }
    return true;
}
