public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    boolean[] visited = new boolean[26];
    while (result.length() < s.length()) {
        char smallest = getSmallest(s, visited);
        result.append(smallest);
        visited[smallest - 'a'] = true;
        char largest = getLargest(s, visited);
        result.append(largest);
        visited[largest - 'a'] = true;
    }
    return result.toString();
}

private char getSmallest(String s, boolean[] visited) {
    char smallest = 'z' + 1;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (visited[c - 'a'] || c > smallest) {
            continue;
        }
        smallest = c;
    }
    return smallest;
}

private char getLargest(String s, boolean[] visited) {
    char largest = 'a' - 1;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (visited[c - 'a'] || c < largest) {
            continue;
        }
        largest = c;
    }
    return largest;
}
