public static int squarePermutations(int[] A) {
    int N = A.length;
    int[] permutations = new int[N];
    int count = 0;

    for (int i = 0; i < N; i++) {
        boolean found = false;
        for (int j = 0; j < N; j++) {
            if (i != j) {
                double sum = A[i] + A[j];
                if (Math.sqrt(sum) % 1 == 0) {
                    permutations[count] = A[j];
                    found = true;
                    break;
                }
            }
        }
        if (!found) {
            permutations[count] = A[i];
        }
        count++;
    }

    int[] currentPermutation = Arrays.copyOf(A, A.length);
    do {
        int[] newPermutation = getNextPermutation(currentPermutation);
        if (isSquareArray(newPermutation)) {
            count++;
        }
        currentPermutation = newPermutation;
    } while (!Arrays.equals(currentPermutation, A));

    return count;
}

private static int[] getNextPermutation(int[] A) {
    int[] B = Arrays.copyOf(A, A.length);
    int i = B.length - 2;
    while (i >= 0 && B[i] > B[i+1]) {
        i--;
    }
    if (i == -1) {
        return B;
    }
    int j = B.length - 1;
    while (j >= 0 && B[j] > B[i]) {
        j--;
    }
    swap(B, i, j);
    j = B.length - 1;
    while (i < j) {
        swap(B, i, j);
        i++;
        j--;
    }
    return B;
}

private static void swap(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
}

public static boolean isSquareArray(int[] A) {
    int N = A.length;
    boolean[] used = new boolean[N];
    for (int i = 0; i < N; i++) {
        if (!used[i]) {
            boolean found = false;
            for (int j = i + 1; j < N; j++) {
                if (!used[j]) {
                    double sum = A[i] + A[j];
                    if (Math.sqrt(sum) % 1 == 0) {
                        used[j] = true;
                        found = true;
                        break;
                    }
                }
            }
            if (!found) {
                return false;
            }
        }
    }
    return true;
}
