    public int countSigns(int[] nums) {
        if (nums.length == 0) {
            return 0;
        }

        Map<Integer, Integer> signMap = new HashMap<>();
        signMap.put(1, 0); // +
        signMap.put(-1, 0); // -
        signMap.put(0, 0); // 0

        for (int num : nums) {
            int sign = 0;
            if (num > 0) {
                sign = 1;
            } else if (num < 0) {
